 "content": "def transform(grid):
    """Expand a V from the input marker; fill interior diagonals every 4 cells."""
    n = len(grid[0])
    center = next((i for i, value in enumerate(grid[0]) if value == 2), n // 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for x in (center - r, center + r):
            if 0 <= x < n:
                out[r][x] = 2
        for x in range(max(0, center - r + 1), min(n, center + r)):
            if (x - r - center) % 4 == 0:
                out[r][x] = 1
    return out
